import AppKit
import CoreImage

/// Official logos for apps that aren't installed in Applications (so macOS has no icon for them).
/// One-color marks come from Simple Icons (CC0) with each brand's color; finished icons come from
/// each company's own website. Trademarks belong to their owners. The `all` table is generated from
/// the downloaded files; the drawing code below it is normal code.
enum BrandLogos {
    enum Kind { case mark, tile, color }
    struct Logo { let data: Data; let kind: Kind; let hex: UInt32 }

    static let all: [String: Logo] = [
        "claude": Logo(data: Data(base64Encoded: "")!, kind: .mark, hex: 0xD97757),
        "codex": Logo(data: Data(base64Encoded: "")!, kind: .mark, hex: 0x000000),
        "cursor": Logo(data: Data(base64Encoded: "")!, kind: .mark, hex: 0x000000),
        "gemini": Logo(data: Data(base64Encoded: "")!, kind: .mark, hex: 0x8E75B2),
        "perplexity": Logo(data: Data(base64Encoded: "")!, kind: .mark, hex: 0x1FB8CD),
        "copilot": Logo(data: Data(base64Encoded: "")!, kind: .mark, hex: 0x000000),
        "zed": Logo(data: Data(base64Encoded: "")!, kind: .mark, hex: 0x084CCF),
        "windsurf": Logo(data: Data(base64Encoded: "")!, kind: .mark, hex: 0x0B100F),
        "elevenlabs": Logo(data: Data(base64Encoded: "PHN2ZyByb2xlPSJpbWciIHZpZXdCb3g9IjAgMCAyNCAyNCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48dGl0bGU+RWxldmVuTGFiczwvdGl0bGU+PHBhdGggZD0iTTQuNjAzNSAwdjI0aDQuOTMxN1Ywem05Ljg2MTMgMHYyNGg0LjkzMTdWMHoiLz48L3N2Zz4=")!, kind: .mark, hex: 0x000000),
        "suno": Logo(data: Data(base64Encoded: "PHN2ZyByb2xlPSJpbWciIHZpZXdCb3g9IjAgMCAyNCAyNCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48dGl0bGU+U3VubzwvdGl0bGU+PHBhdGggZD0iTTE2LjUgMEMyMC42NDIgMCAyNCA1LjM3MyAyNCAxMmgtOWMwIDYuNjI3LTMuMzU4IDEyLTcuNSAxMkMzLjM1OCAyNCAwIDE4LjYyNyAwIDEyaDljMC02LjYyNyAzLjM1OC0xMiA3LjUtMTJaIi8+PC9zdmc+")!, kind: .mark, hex: 0x000000),
        "ollama": Logo(data: Data(base64Encoded: "")!, kind: .mark, hex: 0x000000),
        "lmstudio": Logo(data: Data(base64Encoded: "")!, kind: .mark, hex: 0x000000),
        "grok": Logo(data: Data(base64Encoded: "")!, kind: .tile, hex: 0x000000),
        "kiro": Logo(data: Data(base64Encoded: "")!, kind: .tile, hex: 0x000000),
        "higgsfield": Logo(data: Data(base64Encoded: "")!, kind: .tile, hex: 0x000000),
        "runway": Logo(data: Data(base64Encoded: "")!, kind: .tile, hex: 0x000000),
        "lovable": Logo(data: Data(base64Encoded: "")!, kind: .color, hex: 0xFFFFFF),
        "antigravity": Logo(data: Data(base64Encoded: "")!, kind: .color, hex: 0xFFFFFF),
