extension BrandLogos {
    /// The logo as a macOS-style app icon: a rounded square on the app icon grid (artwork about
    /// 80% of the canvas), so it matches the real installed icons next to it in size and shape.
    static func tile(_ id: String, size: CGFloat = 256) -> NSImage? {
        guard let logo = all[id], let art = NSImage(data: logo.data) else { return nil }
        let image = NSImage(size: NSSize(width: size, height: size), flipped: false) { canvas in
            let inner = canvas.insetBy(dx: size * 0.1, dy: size * 0.1)
            let shape = NSBezierPath(roundedRect: inner, xRadius: inner.width * 0.225, yRadius: inner.width * 0.225)
            // Finished app icons (and Lovable's and Antigravity's site icons, which already
            // include their own background) fill the tile, like real installed icons.
            if logo.kind == .tile || logo.kind == .color {
                NSGraphicsContext.saveGraphicsState()
                shape.addClip()
                if logo.kind == .color { NSColor.white.setFill(); inner.fill() }
                art.draw(in: inner)
                NSGraphicsContext.restoreGraphicsState()
            } else {
                // Black brands use the light version (black mark on white), the way their own app
                // icons look; colored brands put a white mark on their color.
                let dark = (logo.hex >> 16) & 0xFF < 0x20 && (logo.hex >> 8) & 0xFF < 0x20 && logo.hex & 0xFF < 0x20
                (dark ? NSColor.white : color(logo.hex)).setFill()
                shape.fill()
                let box = fit(art.size, in: inner.insetBy(dx: inner.width * 0.16, dy: inner.width * 0.16))
                if dark { art.draw(in: box) } else { whiteMark(art, size: box.size)?.draw(in: box) }
            }
            return true
        }
        return image
    }

    /// The one-color mark in white, for the menu bar pill and the usage circles.
    static func glyph(_ id: String) -> NSImage? {
        if id == "grokbot" { return grokBotMark() }
        guard let logo = all[id], logo.kind == .mark, let art = NSImage(data: logo.data) else { return nil }
        return whiteMark(art, size: fit(art.size, in: NSRect(x: 0, y: 0, width: 96, height: 96)).size)
    }

    /// Grok Bot publishes no one-color logo, so this draws the face from its app icon (a round
    /// head with two slanted eyes) as a white mark with the eyes cut out, like the other marks.
    private static func grokBotMark() -> NSImage {
        NSImage(size: NSSize(width: 96, height: 96), flipped: false) { _ in
            let face = NSBezierPath(ovalIn: NSRect(x: 4, y: 4, width: 88, height: 88))
            face.windingRule = .evenOdd
            // Eye centers, measured from the icon and moved onto a centered face.
            for (x, y) in [(36.0, 52.0), (63.0, 60.0)] {
                let eye = NSBezierPath(roundedRect: NSRect(x: -8, y: -17, width: 16, height: 34), xRadius: 8, yRadius: 8)
                var t = AffineTransform(translationByX: x, byY: y)
                t.rotate(byDegrees: 32)
                eye.transform(using: t)
                face.append(eye)
            }
            NSColor.white.setFill()
            face.fill()
            return true
        }
    }

    private static func whiteMark(_ art: NSImage, size: NSSize) -> NSImage? {
        NSImage(size: size, flipped: false) { r in
            art.draw(in: r)
            NSColor.white.set()
            r.fill(using: .sourceAtop)
            return true
        }
    }

    private static func fit(_ s: NSSize, in r: NSRect) -> NSRect {
        guard s.width > 0, s.height > 0 else { return r }
        let k = min(r.width / s.width, r.height / s.height)
        let w = s.width * k, h = s.height * k
        return NSRect(x: r.midX - w / 2, y: r.midY - h / 2, width: w, height: h)
    }

    private static func color(_ hex: UInt32) -> NSColor {
        NSColor(srgbRed: CGFloat((hex >> 16) & 0xFF) / 255, green: CGFloat((hex >> 8) & 0xFF) / 255,
                blue: CGFloat(hex & 0xFF) / 255, alpha: 1)
    }
}

extension NSImage {
    /// A gray copy of the image, for apps that aren't supported yet. Done on the image itself, so it
    /// looks the same everywhere (SwiftUI's grayscale filter doesn't reach every rendering path).
    func grayscaled() -> NSImage {
        guard let tiff = tiffRepresentation, let ci = CIImage(data: tiff),
              let filter = CIFilter(name: "CIColorControls") else { return self }
        filter.setValue(ci, forKey: kCIInputImageKey)
        filter.setValue(0.0, forKey: kCIInputSaturationKey)
        guard let out = filter.outputImage,
              let cg = CIContext().createCGImage(out, from: out.extent) else { return self }
        return NSImage(cgImage: cg, size: size)
    }
}
